package com.spaceagent.platform.automation;
import com.spaceagent.platform.automation.api.AutomationEventExecutionApplicationApi;import com.spaceagent.platform.automation.application.AutomationEventDispatchWorker;import com.spaceagent.platform.automation.domain.*;import com.spaceagent.platform.automation.infrastructure.memory.InMemoryAutomationTriggerRepository;import java.time.Instant;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.argThat;import static org.mockito.Mockito.*;
class AutomationEventDispatchWorkerTest{@Test void claimsReadyOnceAndRecoversOnlyStaleDispatch(){var now=new AtomicReference<>(Instant.EPOCH);var repo=new InMemoryAutomationTriggerRepository();var events=mock(AutomationEventExecutionApplicationApi.class);var occurrence=new AutomationTriggerPersistence.Occurrence("occurrence","trigger","lineage","subscription","tenant","owner","sha256:"+"a".repeat(64),"sha256:"+"b".repeat(64),AutomationTriggerPersistence.OccurrenceState.READY,Instant.EPOCH,Instant.EPOCH,1,Instant.EPOCH,Instant.EPOCH);repo.createOrFindOccurrence(occurrence);var worker=new AutomationEventDispatchWorker(repo,events,now::get);assertThat(worker.dispatchOne()).isTrue();verify(events).dispatch(argThat(c->c.occurrenceId().equals("occurrence")&&c.expectedOccurrenceRevision()==2));assertThat(worker.dispatchOne()).isFalse();now.set(Instant.EPOCH.plusSeconds(61));assertThat(worker.dispatchOne()).isTrue();verify(events).dispatch(argThat(c->c.expectedOccurrenceRevision()==3));}}
